t,b,c,q=labs[0]
c[0]=('Check prerequisites', 'export MSYS_NO_PATHCONV=1\nkubectl config current-context\nkubectl get nodes\nkubectl get deployments -n ingress-lab\nkubectl get ingressclass traefik\ngit remote -v\n# Docker Desktop only: kubectl config use-context docker-desktop')
labs[0]=(t,b,c,q)
t,b,c,q=labs[2]
c[0]=('Terminal A: Docker Desktop only; KillerCoda uses its access launcher',c[0][1])
b += ' On KillerCoda do not use the local URL or edit a hosts file. Run bash scripts/killercoda-access.sh after setup, keep it running, and open its printed argocd URL for port 8083. The access script sends traffic through Traefik and sets the runtime Argo external URL. Use the same admin login below.'
c[2]=('Read the initial password locally', "kubectl get secret argocd-initial-admin-secret -n argocd -o jsonpath='{.data.password}' | base64 --decode\nprintf '\\n'")
labs[2]=(t,b,c,q)
t,b,c,q=labs[4]
c[0]=('Change the desired replica count in Git', 'sed -i \'s/^replicaCount: 2$/replicaCount: 3/\' charts/nginx/values.yaml\nhelm lint ./charts/nginx --strict\ngit add charts/nginx/values.yaml\ngit commit -m "Practice GitOps: scale nginx to three replicas"\ngit push origin main')
c[3]=('Restore two replicas through Git', 'sed -i \'s/^replicaCount: 3$/replicaCount: 2/\' charts/nginx/values.yaml\ngit add charts/nginx/values.yaml\ngit commit -m "Restore nginx baseline to two replicas"\ngit push origin main\nkubectl annotate application lab-nginx -n argocd argocd.argoproj.io/refresh=hard --overwrite\n# Wait until Details shows the new Git revision, then:\nbash scripts/argocd-sync.sh nginx')
labs[4]=(t,b,c,q)
t,b,c,q=labs[7]
b=b.replace('--grpc-web carries CLI requests over this HTTP ingress.', '--grpc-web works over the dedicated local HTTP API forward shown below; UI access still uses ingress.')
c[0]=('Optional CLI: terminal A, direct API connection on either platform', 'kubectl port-forward -n argocd svc/argocd-server 8090:80 --address 127.0.0.1')
c.insert(1,('Optional CLI: terminal B', 'argocd login localhost:8090 --username admin --plaintext --grpc-web\n# Enter the password interactively. This direct API forward is separate from UI ingress.\nargocd app list --grpc-web\nargocd app get lab-nginx --grpc-web\nargocd app diff lab-nginx --grpc-web\nargocd app history lab-nginx --grpc-web\nargocd app sync lab-nginx --grpc-web\nargocd app wait lab-nginx --sync --health --timeout 180 --grpc-web'))
