css=re.search(r'<style>(.*?)</style>',P('index.html').read_text(encoding='utf-8'),re.S).group(1)
svg='''<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1080 570" role="img"><title>GitOps reconciliation and ingress traffic</title><defs><marker id="arrow" markerWidth="10" markerHeight="10" refX="9" refY="3" orient="auto"><path d="M0 0 L9 3 L0 6" fill="none" stroke="#287b7b"/></marker></defs><style>text{font:16px system-ui;fill:#203a42}.b{fill:white;stroke:#9abdb3;stroke-width:2}.l{fill:none;stroke:#287b7b;stroke-width:2;marker-end:url(#arrow)}</style><rect width="1080" height="570" fill="#eff7f2" rx="20"/><text x="25" y="35">CONTROL LOOP • desired state is pulled from Git; live state is watched from Kubernetes</text><rect class="b" x="25" y="70" width="220" height="85" rx="12"/><text x="40" y="101">Student: edit, test, commit</text><text x="40" y="130">git push → GitHub main</text><path class="l" d="M245 110 H290"/><rect class="b" x="295" y="70" width="220" height="85" rx="12"/><text x="310" y="101">Git repository</text><text x="310" y="130">charts/ + values.yaml</text><path class="l" d="M515 110 H560"/><rect class="b" x="565" y="70" width="245" height="85" rx="12"/><text x="580" y="101">Argo repo-server</text><text x="580" y="130">fetch + Helm rendering</text><path class="l" d="M690 155 V205"/><rect class="b" x="540" y="210" width="300" height="85" rx="12"/><text x="555" y="240">Application-controller</text><text x="555" y="268">compare → diff → sync → health</text><path class="l" d="M540 250 H340"/><rect class="b" x="25" y="210" width="310" height="85" rx="12"/><text x="40" y="240">Kubernetes API / ingress-lab</text><text x="40" y="268">Deployment + Service + Ingress</text><path class="l" d="M335 280 H500 V310 H690 V295"/><text x="350" y="338">watch live state; selfHeal repairs drift</text><text x="25" y="385">DATA PLANE • application traffic does not pass through the Argo CD control plane</text><rect class="b" x="25" y="415" width="205" height="70" rx="12"/><text x="40" y="443">Browser / curl entry URL</text><text x="40" y="468">Host: lab / generated</text><path class="l" d="M230 450 H275"/><rect class="b" x="280" y="415" width="180" height="70" rx="12"/><text x="295" y="445">Traefik controller</text><text x="295" y="470">Ingress host rules</text><path class="l" d="M460 450 H505"/><rect class="b" x="510" y="415" width="235" height="70" rx="12"/><text x="525" y="445">3 application Services</text><text x="525" y="470">NGINX / Prom / Grafana</text><path class="l" d="M745 450 H790"/><rect class="b" x="795" y="415" width="250" height="70" rx="12"/><text x="810" y="445">2 ready pods per app</text><text x="810" y="470">same workloads as Lab 1</text><text x="25" y="535">Argo UI: argocd.lab.test:8080 → Traefik → argocd-server Service → server pod (separate from apps)</text></svg>'''
P('docs/gitops-architecture.svg').write_text(svg,encoding='utf-8')
a=['<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Lab 2 • GitOps with Argo CD</title><style>'+css+'</style><header><div class="eyebrow">SECTION 2 / GITOPS WITH ARGO CD</div><h1>Commit the intent.<br>Watch it reconcile.</h1><p class="lead">Take today’s three ingress applications from Helm deployment to a Git-driven reconciliation loop.</p><div class="tags"><span>11 hands-on labs</span><span>Answers included</span><span>Same charts &amp; URLs</span><span>Manual → auto → self-heal → prune</span></div><p><a href="index.html">← Section 1: Ingress foundations</a> · <a href="environments.html">Git Bash / KillerCoda setup</a> · <a href="docs/ARGOCD-TEST-RESULTS.md">Local verification report</a></p></header><main><nav>']
a += [f'<a href="#lab{i}">{i:02} {E(t)}</a>' for i,(t,*_) in enumerate(labs,1)]
a+=['</nav><section><h2>Two flows, one cluster</h2><img src="docs/gitops-architecture.svg" alt="Git changes flow through Argo CD to Kubernetes while browser traffic flows through Traefik to Services and two pods per application."><p>Argo CD manages desired configuration. It does not serve the three application requests or replace their ingress controller.</p><div class="note">Commands use Git Bash on Windows or Linux Bash inside KillerCoda, from this repository root. Export MSYS_NO_PATHCONV=1 in Git Bash to prevent kubectl path rewriting. Keep credentials out of Git. The public repository URL is preconfigured for vrdipu/ingress-lab; students should use their own fork for write exercises.</div></section>']
for i,(title,body,cmds,qa) in enumerate(labs,1):
 a.append(f'<section id="lab{i}"><span class="number">LAB 2.{i:02}</span><h2>{E(title)}</h2><p>{E(body)}</p>')
 if i==3:a.append('<p><a href="http://argocd.lab.test:8080">Open Argo CD UI</a> · Username: <code>admin</code>. Docker Desktop hosts file only (KillerCoda uses generated URLs): <code>C:\\Windows\\System32\\drivers\\etc\\hosts</code>.</p>')
 for label,code in cmds:a.append('<h3>'+E(label)+'</h3><div class="code"><button type="button">Copy</button><pre><code>'+E(code)+'</code></pre></div>')
 a.append('<h3>Interview questions &amp; answers</h3>')
 for q,ans in qa:a.append('<details class="interview" open><summary>'+E(q)+'</summary><p><strong>Answer:</strong> '+E(ans)+'</p></details>')
 a.append('</section>')
a.append('<section><h2>Every GitOps manifest, explained</h2><p>argocd-values.yaml configures the control plane. AppProject restricts the source and destination. Applications point to the existing charts and begin in manual mode. argocd-ingress.yaml routes the UI. The exercise ConfigMap is disposable.</p>')
